namespace ghidra.app.plugin.core.progmgr;




using ghidra.framework.plugintool;
using ghidra.program.model.listing;

/**
 * Action class for the "Undo" action
 */
public class UndoAction : AbstractUndoRedoAction {
	public static readonly string SUBGROUP = "1Undo";

	public UndoAction(ProgramManagerPlugin plugin, PluginTool tool) : base(tool, plugin, "Undo", "icon.undo", "ctrl Z", SUBGROUP)
    {
	}

	/* @Override */
	protected void doAction(Program program, int count)
    {
		for (int i = 0; i < count; i++) {
			program.undo();
		}
	}

	/* @Override */
	protected bool canPerformAction(Program program) {
		return program != null && program.canUndo();
	}

	/* @Override */
	protected string getUndoRedoDescription(Program program) {
		return program.getUndoName();
	}

	/* @Override */
	protected List<string> getDescriptions(Program program) {
		return program.getAllUndoNames();
	}

}
